let locale=(localStorage.getItem(KEY)||'en').toLowerCase()==='ar'?'ar':'en';
export function getLocale(){return locale}
export function setLocale(value){locale=String(value||'en').toLowerCase()==='ar'?'ar':'en';localStorage.setItem(KEY,locale);applyLocale();return locale}
export function cycleLocale(){return setLocale(locale==='ar'?'en':'ar')}
export function applyLocale(){document.documentElement.lang=locale;document.documentElement.dir=locale==='ar'?'rtl':'ltr';document.documentElement.dataset.locale=locale;if(typeof CustomEvent!=='undefined')document.dispatchEvent?.(new CustomEvent('one-locale-change'));return locale}
export function initLocale(){applyLocale();return locale}
export function t(key,vars={}){let s=locale==='ar'?(AR[key]??key):key;for(const [k,v] of Object.entries(vars||{}))s=s.replaceAll(`{${k}}`,String(v));return s}
export function hasArabicTranslation(key){return Object.prototype.hasOwnProperty.call(AR,key)}
export function langButton(){return locale==='ar'?'EN':'ع'}
export function direction(){return locale==='ar'?'rtl':'ltr'}
export function userMessage(message=''){
  const m=String(message||''); if(!m)return m; if(locale!=='ar')return m;
  if(AR[m])return AR[m];
  let x=m.match(/^Wait for (\d+) more responses? or choose to close anyway\.$/);if(x)return `انتظر ${x[1]} إجابة إضافية أو اختر الإغلاق رغم ذلك.`;
  x=m.match(/^Course (.+) version (.+) is not installed\.$/);if(x)return `الدورة ${x[1]} بالإصدار ${x[2]} غير مثبتة.`;
  x=m.match(/^Module (.+) requires a title\.$/);if(x)return `الوحدة ${x[1]} تحتاج إلى عنوان.`;
  x=m.match(/^Duplicate module id: (.+)$/);if(x)return `يوجد معرّف وحدة مكرر: ${x[1]}`;
  x=m.match(/^Module (.+): every activity requires an id\.$/);if(x)return `كل نشاط في الوحدة ${x[1]} يحتاج إلى معرّف داخلي.`;
  x=m.match(/^Duplicate activity id: (.+)$/);if(x)return `يوجد معرّف نشاط مكرر: ${x[1]}`;
  x=m.match(/^Activity (.+) uses unsupported type: (.+)\.$/);if(x)return `النشاط ${x[1]} يستخدم نوعًا غير مدعوم: ${x[2]}.`;
  x=m.match(/^Activity (.+): at least two options are required\.$/);if(x)return `النشاط ${x[1]} يحتاج إلى خيارين على الأقل.`;
  x=m.match(/^Activity (.+) has no title\.$/);if(x)return `النشاط ${x[1]} لا يحتوي على عنوان.`;
  x=m.match(/^Module (.+): every mission requires an id\.$/);if(x)return `كل مهمة في الوحدة ${x[1]} تحتاج إلى معرّف داخلي.`;
  x=m.match(/^Duplicate mission id: (.+)$/);if(x)return `يوجد معرّف مهمة مكرر: ${x[1]}`;
  x=m.match(/^Mission (.+) requires a title\.$/);if(x)return `المهمة ${x[1]} تحتاج إلى عنوان.`;
  x=m.match(/^Mission (.+) has no guided steps\.$/);if(x)return `المهمة ${x[1]} لا تحتوي على خطوات إرشادية.`;
  x=m.match(/^Referenced module file not found: (.+)$/);if(x)return `لم يتم العثور على ملف الوحدة المشار إليه: ${x[1]}`;
  x=m.match(/^Referenced module file is invalid JSON: (.+)$/);if(x)return `ملف الوحدة المشار إليه ليس JSON صالحًا: ${x[1]}`;
  x=m.match(/^Course file not found: (.+)$/);if(x)return `لم يتم العثور على ملف الدورة: ${x[1]}`;
  x=m.match(/^Manifest file missing: (.+)$/);if(x)return `ملف مذكور في البيان مفقود: ${x[1]}`;
  x=m.match(/^Checksum mismatch: (.+)$/);if(x)return `فشل التحقق من بصمة الملف: ${x[1]}`;
  x=m.match(/^Referenced asset not found: (.+)$/);if(x)return `لم يتم العثور على المورد المشار إليه: ${x[1]}`;
  x=m.match(/^Unsafe asset reference: (.+)$/);if(x)return `مرجع مورد غير آمن: ${x[1]}`;
  x=m.match(/^Asset reference could not be verified in a JSON-only import: (.+)$/);if(x)return `تعذر التحقق من المورد في استيراد JSON فقط: ${x[1]}`;
  x=m.match(/^Activity (.+): content block (\d+) uses unsupported type: (.+)\.$/);if(x)return `النشاط ${x[1]}: كتلة المحتوى ${x[2]} تستخدم نوعًا غير مدعوم: ${x[3]}.`;
  x=m.match(/^Activity (.+): (.+) block (\d+) requires an asset or src\.$/);if(x)return `النشاط ${x[1]}: كتلة ${x[2]} رقم ${x[3]} تحتاج إلى مورد أو رابط مصدر.`;
  x=m.match(/^Activity (.+): chart block (\d+) uses unsupported chart type: (.+)\.$/);if(x)return `النشاط ${x[1]}: الرسم ${x[2]} يستخدم نوعًا غير مدعوم: ${x[3]}.`;
  x=m.match(/^Activity (.+): chart block (\d+) requires a data array\.$/);if(x)return `النشاط ${x[1]}: الرسم ${x[2]} يحتاج إلى مصفوفة بيانات.`;
  x=m.match(/^Activity (.+): response_scope must be individual or team\.$/);if(x)return `النشاط ${x[1]}: يجب أن تكون الاستجابة فردية أو جماعية.`;
  x=m.match(/^Activity (.+): team_challenge should normally use response_scope 'team'\.$/);if(x)return `النشاط ${x[1]}: يُفضّل أن يستخدم التحدي الجماعي نطاق استجابة الفريق.`;
  x=m.match(/^Activity (.+): minimum_response_rate must be greater than 0 and at most 1\.$/);if(x)return `النشاط ${x[1]}: نسبة الاستجابات الدنيا يجب أن تكون أكبر من 0 ولا تتجاوز 1.`;
  x=m.match(/^Activity (.+): minimum_responses must be at least 1\.$/);if(x)return `النشاط ${x[1]}: الحد الأدنى للاستجابات يجب أن يكون 1 على الأقل.`;
  x=m.match(/^Activity (.+): flow\.next_activity_id points to missing activity (.+)\.$/);if(x)return `النشاط ${x[1]} يشير إلى نشاط تالٍ غير موجود: ${x[2]}.`;
  x=m.match(/^Activity (.+): branch points to missing activity (.+)\.$/);if(x)return `النشاط ${x[1]} يحتوي على فرع يشير إلى نشاط غير موجود: ${x[2]}.`;
  x=m.match(/^Activity (.+): unknown objective id (.+)\.$/);if(x)return `النشاط ${x[1]} يشير إلى هدف غير موجود: ${x[2]}.`;
  x=m.match(/^Mission (.+): unknown objective id (.+)\.$/);if(x)return `المهمة ${x[1]} تشير إلى هدف غير موجود: ${x[2]}.`;
  x=m.match(/^Mission (.+): unsupported submission type (.+)\.$/);if(x)return `المهمة ${x[1]} تستخدم نوع تسليم غير مدعوم: ${x[2]}.`;
  x=m.match(/^Activity (.+): invalid true\/false correct_answer\.$/);if(x)return `النشاط ${x[1]} يحتوي على إجابة صح/خطأ غير صالحة.`;
  x=m.match(/^Activity (.+): rating max must be greater than min\.$/);if(x)return `النشاط ${x[1]}: الحد الأعلى للتقييم يجب أن يكون أكبر من الحد الأدنى.`;
  x=m.match(/^Activity (.+): numeric answer max must be greater than or equal to min\.$/);if(x)return `النشاط ${x[1]}: الحد الأعلى للإجابة الرقمية يجب ألا يقل عن الحد الأدنى.`;
  x=m.match(/^Activity (.+): results display '(.+)' will fall back to cards\.$/);if(x)return `النشاط ${x[1]}: عرض النتائج ${x[2]} غير مدعوم وسيتم استخدام البطاقات بدلًا منه.`;
  x=m.match(/^Unsupported or unsafe package asset type: (.+)$/);if(x)return `نوع مورد غير مدعوم أو غير آمن داخل الحزمة: ${x[1]}`;
  return m;
}

export function tForLocale(key,language,vars={}){let text=language==='ar'?(AR[key]??key):key;for(const [k,v] of Object.entries(vars||{}))text=text.replaceAll(`{${k}}`,String(v));return text}
